COMMON = """Дата: 18 сентября 2026 года. Основания: [бриф](brief.md), [конкурентный анализ](competitive_analysis_final.md), [UX-аудит](audit/audit_report.md), [прото-персоны](personas.md) и [UX-паттерны](competitor_ux_patterns.md). Файлы `interview_*.md` в проекте не найдены; интервью и количественные оценки спроса не подменяются гипотезами.

**Ограничение scope:** заказчик уже подтвердил весь перечисленный в брифе функционал сразу. Поэтому «MVP» здесь означает первую рабочую версию с полным согласованным набором, а не урезанный набор карт без replay, PDF или сигналов. Порядок разработки не меняет объём выпуска.

П1 — дизайнер (primary), П2 — PM, П3 — участник. Приоритеты персон предложены в `personas.md`; secondary не означает отложенный поток. Права коллег одинаковые. Предложения из аудита/персон не выдаются за подтверждённые пожелания заказчика.
"""


def feature_table():
    lines = ["| ID / фича или требование | Описание | Источник | Для кого критично / полезно | Статус основания |", "| --- | --- | --- | --- | --- |"]
    for ident, name, desc, refs, roles, status, priority, reason in FEATURES:
        lines.append(f"| **{ident} — {name}** | {desc} | {refs} | {roles} | {STATUS[status]} |")
    return "\n".join(lines)


def priorities():
    parts = []
    for priority, heading in [("Must", "Must have — первая версия"), ("Should", "Should have — кандидаты сразу после первой версии"), ("Could", "Could have — при доказанной пользе и наличии ресурсов"), ("Won't", "Won't have now — вне этой версии")]:
        parts.append(f"## {heading}\n\n| ID / требование | Почему этот приоритет | Основание решения |\n| --- | --- | --- |")
        for ident, name, desc, refs, roles, status, category, reason in FEATURES:
            if category == priority:
                parts.append(f"| {ident} — {name} | {reason} | {STATUS[status]}; {refs} |")
        parts.append("")
    return "\n".join(parts)


def scope_list():
    return "\n".join(f"- **{ident} — {name}.** {desc}" for ident, name, desc, refs, roles, status, category, reason in FEATURES if category == "Must")


def render():
    counts = Counter(row[6] for row in FEATURES)
    excluded_count = counts["Won't"]
    inventory = "# Полный список фич и требований\n\n" + COMMON + """
## Как собран список

Функции объединены по результату для пользователя, а не по каждому повторному упоминанию. F — функции и интерфейсные требования; N — условия работы и приёмки, они не считаются отдельными экранами. Поле «статус основания» отделяет подтверждённые требования от предложений. Приоритет хранится отдельно в [MoSCoW](prioritization.md).

Наблюдения аудита относятся к скриншотам Maze, преимущественно к Figma Prototype Test, и не являются пользовательскими интервью. Общие карты, сбор поведения и replay дают ориентир по категории; одинаковый конструктор заданий и PDF у всех пяти конкурентов не подтверждены. Доказанной уникальной функции нет: цельный процесс — проверяемая гипотеза удобства, а не установленная ниша.

## Реестр

""" + feature_table() + f"\n\nВсего: {len(FEATURES)} позиций, включая 6 условий N. Это инвентаризация, не оценка трудозатрат.\n"
    inventory += """
## Что не превращено в отдельную фичу

- Стек, сроки, бюджет, дизайн-система, требования доступности, схема событий и состав PDF — открытые решения внутри соответствующих функций, а не придуманная реализация.
- Скорость, число шагов и финансовый эффект не получили вымышленных целевых значений.
- Камера, AI, типы опросов и платные уровни, увиденные у конкурента, не добавляются только из-за наличия на его экране.
- Поиск и фильтры разделены: базовый контекст обязателен в предложенном scope, сохранённые наборы и поиск большого каталога — дополнительные удобства.
"""
    prioritization = "# Приоритизация по MoSCoW\n\n" + COMMON + """
## Правило решения

1. Все подтверждённые функции первой версии — **Must**, согласно прямому решению заказчика. Даже наличие бесплатного аналога или secondary-персона не понижает их приоритет.
2. Минимальные опоры сквозного сценария и корректности данных предложены как **Must** и явно помечены. Это аналитическое решение для проекта, не утверждение, что заказчик отдельно согласовал каждый паттерн.
3. **Should** — ускорение уже доступного основного сценария после первой версии; **Could** — дополнительные непроверенные удобства; **Won't now** — ранее отложенное или не входящее в подтверждённую задачу.
4. Критерии JTBD, необходимости и распространённости из директивы используются как основания, а не требование одновременного совпадения всех трёх. Иначе из scope ошибочно исчезнут прямо запрошенные функции, которых нет у всех конкурентов.

Тепловая карта — главный приоритет интерфейса, но не единственная функция выпуска. Нет оснований для числового рейтинга ROI/RICE: частота использования, бюджет и оценки реализации отсутствуют.

""" + priorities()
    prioritization += f"\nИтог: **{counts['Must']} Must**, **{counts['Should']} Should**, **{counts['Could']} Could**, **{excluded_count} Won't now**. Число позиций не равно объёму разработки: определения метрик и настройка доступа имеют другую природу, чем полноценные функции.\n"
    prioritization += """
## Предлагаемый порядок реализации внутри первой версии

1. Согласовать события, идентификаторы, границы попытки, контекст страницы/устройства и хранение: эти решения влияют сразу на карты, воронку и запись.
2. Проверить сквозной сбор на контрольном прототипе: подключение → задание/свободный режим → ссылка → участник → данные.
3. Реализовать обязательные представления анализа: обе карты, воронку, replay, все четыре сигнала, содержимое ввода, полноту и связанную навигацию.
4. Завершить PDF, сообщения об ошибках и проверку контрольного исследования с согласованным масштабом.

Это порядок снижения неопределённости, не план выпуска урезанного продукта. Оценки сроков можно сделать после выбора технического решения; дата следующей версии не назначается.
"""
    scope = "# Scope первой версии (MVP)\n\n" + COMMON + """
## 1. Одно предложение

Внутренний веб-сервис позволяет небольшой команде проводить тесты живых интерфейсов по ссылке с заданиями или свободным изучением и находить проблемы через карты частоты и первого клика, воронки, воспроизведение действий с содержимым ввода, четыре сигнала затруднений и экспорт PDF.

## 2. Состав первой версии — только Must have

Ниже перечислены все Must из [приоритизации](prioritization.md); источники и статус подтверждения каждой позиции — в [реестре](features_list.md). Предлагаемые опоры сценария не заменяют подтверждённые функции.

""" + scope_list() + """

## 3. Основной сценарий дизайнера: от входа до результата

Это предлагаемая структура экранов, а не утверждённый макет. Один экран может объединить несколько шагов.

| Шаг / экран | Что делает дизайнер | Видимый результат / критерий перехода |
| --- | --- | --- |
| 1. Вход и исследования | Открывает сервис с правами коллеги, создаёт или выбирает исследование | Видно название, состояние и связанные результаты; способ авторизации ещё выбирается |
| 2. Подключение интерфейса | Указывает прототип, устанавливает код, запускает контрольное действие | Понятно, поступают ли данные и доступен ли интерфейс участнику |
| 3. Настройка | Выбирает задания или свободный режим; вводит/выбирает сценарий и настраивает критерий | Текст задания отделён от целевой страницы, кнопки или цепочки; для свободного режима не выдумывается обязательный успех |
| 4. Проверка и запуск | Проходит контрольную попытку, проверяет сохранение, получает ссылку и сам отправляет её | Готовность и сохранение объяснены; отдельная встроенная панель Preview не требуется |
| 5. Прохождение — ветка участника | Участник открывает ссылку без регистрации на подходящем устройстве, получает инструкцию и выполняет действия | Созданы номер и данные попытки; завершение, отказ и потеря данных различаются по согласованным правилам |
| 6. Участники и состояние данных | Дизайнер смотрит поступившие результаты | Видно, какие попытки завершены и какие данные неполны; 20 — цель контрольного исследования, не автоматический предел |
| 7. Результаты — карта в центре | Выбирает контекст, смотрит частоту/первый клик, воронку и сигналы | Названы страница/состояние, выборка, знаменатели и режим; цвета карты имеют объяснение |
| 8. Деталь и запись | Открывает связанного участника, воспроизводит действия и введённое содержимое | Может проверить интерпретацию и вернуться с прежним контекстом; четыре сигнала доступны без расширенной сводки пути |
| 9. PDF | Проверяет состав и экспортирует результаты | Читаемый документ соответствует выбранному исследованию и контексту; точный состав требует решения |

PM использует те же права и может включиться на любом шаге; участник не видит аналитический дашборд. Свободное изучение проходит тот же сбор и анализ без навязанного сценарного критерия.

## 4. Что не входит: три Should после первой версии

Это предложенные кандидаты ближайшего развития, а не утверждённое обещание сроков. Ни одна подтверждённая функция брифа сюда не перенесена.

| ID / кандидат | Почему можно после первой версии | Что уже остаётся в первой версии |
| --- | --- | --- |
| F27 — ускоренный разбор длинных записей | Польза зависит от длины сессий; можно начать с обычного просмотра | Replay, все четыре сигнала, участники и переход из результата к записи |
| F28 — встроенный предпросмотр редактора | Это удобство компоновки, а не единственный способ проверить тест | Контрольное прохождение, инструкция и проверка подключения |
| F29 — шаблон/дублирование целого исследования | Частота повторных исследований неизвестна | Создание исследования и обязательный выбор задания из списка F04 |

Could: сохранённые фильтры F30, поиск большого каталога F31, расширенные команды F32. Они не заменяют базовые фильтры, понятный список и сохранение настроек.

Won't now: Figma F33, Notion F34, мобильный дашборд F35, AI F36, камера/голос F37, публичный SaaS и сложные роли F38, покупка участников/авторассылка F39. Участие с мобильного устройства остаётся в scope.

## 5. Решения до реализации и критерии проверки

Scope функций определён, но он ещё не является техническим заданием с закрытыми вопросами.

| Открытое решение | Где влияет | Что нужно определить или проверить |
| --- | --- | --- |
| Схема цели и попытки | F05, F10–F16, N04 | Как выбирать кнопку/событие, откуда считать первый клик, как завершать попытку и учитывать повтор; пороги сигналов |
| Контекст карты | F09–F10, F22, N04 | Различение страниц, модалок, состояний, размеров и версий; проверка наложения на контрольном интерфейсе |
| Список заданий | F04 | Встроенный набор или сохранённые задания команды; выбор обязателен, механизм открыт |
| Полнота записи | F12, F17, F23 | Поддерживаемые поля, переходы и разрывы связи; какие пропуски можно обнаружить и как их показать |
| Доступ и данные | F19–F21, N05–N06 | Размещение, вход коллег, информирование участника, характер вводимых данных, сроки хранения и удаление; ни одно значение не назначено как факт |
| PDF | F18 | Обязательные разделы и визуализации, отражение выборки и ограничений; генерация и проверка читаемости |
| Качество интерфейса | F25–F26, N01 | Визуальный стиль, доступность, сообщения об ошибках и перечень поддерживаемых браузеров |
| Ресурсы | Весь Must | Бюджет, стек, сроки и ответственность за установку/поддержку; снижение scope не подменяет эти решения |

Подтверждённая проверка результата: самостоятельный запуск, данные 20 участников всего и найденные проблемные места. Предлагаемые проверки качества: известная цепочка действий правильно отражена в карте/воронке/replay; клики на одном URL и в модалке не смешаны с другим состоянием; пропущенные данные не считаются провалом молча; PDF соответствует дашборду. Показатели скорости и проценты точности пока не утверждены.
"""
    return {"features_list.md": inventory, "prioritization.md": prioritization, "mvp_scope.md": scope}


def main():
    for filename in ("brief.md", "competitive_analysis_final.md", "audit/audit_report.md", "personas.md", "competitor_ux_patterns.md"):
        if not (ROOT / filename).is_file():
            raise FileNotFoundError(filename)
    if list(ROOT.rglob("interview_*.md")):
        raise RuntimeError("Interview files found: review new evidence before generating this version")
    ids = [row[0] for row in FEATURES]
    assert len(ids) == len(set(ids)) == 45
    assert all(row[6] == "Must" for row in FEATURES if row[5] == "B")
    assert {row[0] for row in FEATURES if row[6] == "Should"} == {"F27", "F28", "F29"}
    documents = render()
    assert set(re.findall(r"^- \*\*((?:F|N)\d+) —", documents["mvp_scope.md"], re.M)) == {row[0] for row in FEATURES if row[6] == "Must"}
    for name in documents:
        if (ROOT / name).exists():
            raise FileExistsError(f"Refusing to overwrite: {name}")
    for name, text in documents.items():
        assert "\ufffd" not in text
        for target in re.findall(r"\]\(([^)]+)\)", text):
            assert (ROOT / target).is_file() or target in documents, target
    for name, text in documents.items():
        with (ROOT / name).open("x", encoding="utf-8", newline="\n") as stream:
            stream.write(text)
        assert (ROOT / name).read_text(encoding="utf-8") == text
        print("Created and verified: " + name)
    print("Validated 45 IDs, all binding requirements in Must, scope/MoSCoW consistency and local links")


if __name__ == "__main__":
    main()
